const timelineData=[{"y":"1","icon":"🔤","label":"El token","text":"La pieza en que se parte el texto: en español, <strong>tres o cuatro letras</strong> en promedio. <strong>Por qué importa:</strong> todo se cuenta y se paga en tokens, tanto lo que entra como lo que sale. <strong>En casa:</strong> es la unidad en la que se mide el costo del trabajo de cada tanda."},{"y":"2","icon":"🪟","label":"La ventana de contexto","text":"Todo lo que cabe en una conversación: tus mensajes, los archivos y sus respuestas. Los modelos grandes de 2026 llegan al <strong>millón de tokens</strong>, unas 750.000 palabras. <strong>Si se llena:</strong> hay que resumir o empezar de nuevo. <strong>En casa:</strong> por eso un corte de luz se lleva el hilo entero."},{"y":"3","icon":"📚","label":"El entrenamiento","text":"La etapa anterior, larguísima, en que leyó enormes cantidades de texto y ajustó sus números. <strong>Clave:</strong> cuando tú la usas <strong>ya no aprende</strong>. Lo que le expliques hoy no queda para mañana, y su conocimiento termina en la fecha de su corte."},{"y":"4","icon":"🎲","label":"La predicción","text":"En cada paso calcula qué palabra es más probable y elige una, con esa ya incluida vuelve a calcular. <strong>Consecuencia:</strong> dos respuestas a la misma pregunta no son idénticas, y la máquina no distingue entre acertar y sonar bien."},{"y":"5","icon":"🌫️","label":"La alucinación","text":"Inventar con seguridad: una cita con autor y página, una ley, una función que no existe. <strong>Por qué pasa:</strong> es la misma predicción funcionando donde no había con qué acertar, así que lo inventado <strong>tiene la forma exacta</strong> de lo verdadero. <strong>Aviso:</strong> cuanto más específico y más redondo suena un dato, más conviene abrir la fuente."},{"y":"6","icon":"📋","label":"El encargo","text":"Lo que le pides, con sus cinco partes: quién lo usa, para qué, con qué reglas, un ejemplo parecido y cuándo está terminado. <strong>Regla:</strong> lo que no le digas, lo rellena con lo más probable, que casi nunca es lo que hacía falta."},{"y":"7","icon":"🔎","label":"La verificación","text":"Comprobar en la fuente real lo comprobable: contar las páginas del PDF, rehacer la cuenta, abrir el enlace, revisar la cita. <strong>Es lo único</strong> que convierte una respuesta en algo que se puede firmar. <strong>En casa:</strong> el PDF es el único juez, y esa norma nació de un error de esta misma máquina."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

