const parteData={"token":{"nombre":"El token","icon":"🔤","estructura":{"title":"Qué es","info":"• La pieza en que se parte el texto antes de procesarlo<br>• En español, <strong>tres o cuatro letras</strong> en promedio<br>• Una palabra corta es un token; una larga, dos o tres"},"funcion":{"title":"Cómo funciona","info":"• Todo se cuenta en tokens: lo que entra y lo que sale<br>• Se paga por ambos, y <strong>lo que sale cuesta bastante más</strong><br>• En julio de 2026, un modelo grande ronda 5 dólares por millón de tokens de entrada y 25 por millón de salida"},"enfermedades":{"title":"Dónde falla","info":"• Contar tokens a ojo engaña: el código y los acentos gastan más<br>• Cada modelo cuenta distinto, así que la cuenta de uno no vale para otro<br>• Un archivo pegado «gratis» puede costar más que toda la conversación"},"cuidados":{"title":"En el proyecto","info":"• El motor de una misión pesa más de 100.000 tokens: pegarlo entero cuesta<br>• Por eso se lee cada archivo grande <strong>una sola vez</strong> por turno<br>• Y por eso las tandas grandes salen más baratas que los mensajitos"}},"contexto":{"nombre":"El contexto","icon":"🪟","estructura":{"title":"Qué es","info":"• Todo lo que cabe en una conversación<br>• Los modelos grandes de 2026 llegan al <strong>millón de tokens</strong> (unas 750.000 palabras)<br>• Incluye tus mensajes, los archivos y todas sus respuestas"},"funcion":{"title":"Cómo funciona","info":"• En cada turno se le manda <strong>todo</strong> otra vez: no recuerda<br>• Cuando se llena, hay que resumir o empezar de nuevo<br>• La caché abarata la parte repetida a alrededor de la décima parte, pero dura pocos minutos"},"enfermedades":{"title":"Dónde falla","info":"• Cerrada la conversación, se acabó: no hay memoria entre sesiones<br>• Un corte de luz se lleva el hilo entero<br>• Con la ventana muy llena, lo del principio pesa menos en la respuesta"},"cuidados":{"title":"En el proyecto","info":"• La memoria del proyecto vive en el repositorio, no en la máquina<br>• Commit en cada punto de control, con el porqué en el mensaje<br>• Al cambiar de tema conviene empezar conversación limpia"}},"alucinacion":{"nombre":"La alucinación","icon":"🌫️","estructura":{"title":"Qué es","info":"• Inventar con seguridad: una cita, una ley, un dato, una función<br>• No es una mentira: <strong>no hay intención</strong>, hay predicción<br>• Lo inventado tiene la forma exacta de lo verdadero"},"funcion":{"title":"Cómo funciona","info":"• Donde no hay con qué acertar, igual predice lo más probable<br>• Y lo más probable <strong>se parece</strong> a una respuesta correcta<br>• Por eso una cita falsa trae autor, página y año, todo bien puesto"},"enfermedades":{"title":"Dónde falla","info":"• Peor en datos muy específicos: páginas, artículos de ley, cifras<br>• Peor cuando no le diste la fuente y le pediste que recordara<br>• Preguntar dos veces no sirve: la segunda respuesta se predice igual"},"cuidados":{"title":"En el proyecto","info":"• De aquí salió la norma 6: el PDF es el único juez<br>• Todo dato con fuente se abre y se comprueba antes de publicar<br>• Y cada invención cazada se apunta en Destellos: esa lista es tu detector"}},"encargo":{"nombre":"El encargo","icon":"📋","estructura":{"title":"Qué es","info":"• Lo que le pides, con sus cinco partes<br>• <strong>Quién</strong> lo usa · <strong>para qué</strong> · <strong>con qué reglas</strong> · un <strong>ejemplo</strong> · <strong>cuándo termina</strong><br>• Se parece más a una orden de trabajo que a una pregunta"},"funcion":{"title":"Cómo funciona","info":"• Lo que no le digas, lo rellena con lo más probable<br>• Un ejemplo parecido vale más que tres párrafos de explicación<br>• Una tarea por encargo, de un tamaño que se pueda revisar"},"enfermedades":{"title":"Dónde falla","info":"• Encargo de una línea: resultado genérico que hay que rehacer<br>• Encargo enorme: resultado enorme que nadie lee entero<br>• Sin criterio de terminado, la máquina decide ella cuándo terminó"},"cuidados":{"title":"En el proyecto","info":"• Las normas de F.A.R.O son parte del encargo, no un extra<br>• Nunca entran nombres ni notas de menores en un encargo<br>• Y siempre se dice qué se considera terminado: diez páginas medidas, respuestas repartidas, sin guiones largos"}}};
let labParte='token',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente verificador en formación!','¡Usas bien la máquina!','¡Dueño de la herramienta!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó la Etapa 1 de la Ruta de la Máquina que Predice (La máquina que predice)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

